input.sparql:
SELECT ?z2 ?z1 ?ts2 ?ts1 ?o2 ?o1 WHERE {
  ?z2 rdfs:label "Perimeter_top_ZN_2".
  ?z1 rdfs:label "Perimeter_top_ZN_1".
 OPTIONAL { ?o2 brick:isPointOf ?z2 ; a brick:Occupancy ; ref:hasTimeseriesId ?ts2 }
  OPTIONAL { ?o1 brick:isPointOf ?z1 ; a brick:Occupancy ; ref:hasTimeseriesId ?ts1 }
}

SELECT ?p ?cls ?ts ?z WHERE {
  ?p a brick:PeopleFlowSensor .
  ?p brick:isPointOf ?z .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?cls ?ts WHERE {
  ?p brick:isPointOf ?z .
  ?z rdfs:label ?l .
  FILTER (regex(?l, "Perimeter_top_ZN"))
  FILTER regex(str(?cls), "Occupancy|PeopleFlow|Occupant", "i")
}

SELECT ?p ?z ?ts WHERE {
  ?p a brick:Occupancy_Sensor .
  ?p brick:isPointOf ?z .
  ?z rdfs:label ?l .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}
